function out = situationAdvice(id)
%SITUATIONADVICE  The situations of the "Use recommended" button of the filter panel (English).
%   A = SITUATIONADVICE()      struct array with the fields
%         id      short name ('night', 'small', ...)
%         title   text of the drop-down list
%         chain   struct array (name, p) for APPLYPREFILTERS; empty = "no filter is the best choice"
%         why     one or two sentences: why this choice
%         measured  what was measured on the 16 held-out test photos (README section 5a''''''')
%         findAll   true: "Use recommended" also ticks "Find ALL plates" (photos with several cars)
%   lines = SITUATIONADVICE(id)   the text shown in the panel: the filters, how to enter them by hand,
%         why, and what was measured (cell array of lines)
%   The long explanation of every filter in every situation, with pictures, is docs/Filter_Guide.pdf.

A = table_();
if nargin < 1, out = A;  return; end
k = find(strcmp({A.id}, id), 1);
if isempty(k), error('situationAdvice:id', 'Unknown situation "%s".', id); end
a = A(k);
ops = prefilterOps();
lines = {upper(a.title), ''};
if isempty(a.chain)
    lines = [lines, {'Filters: none. "Filter 1" to "Filter 4" were cleared, which means the original photo is used.'}];
    lines = [lines, {'To compare anyway: choose one filter in the list of "Filter 1", then press "Compare with original".'}];
else
    lines = [lines, {'Filters put into "Filter 1", "Filter 2" ... (in this order):'}];
    for q = 1:numel(a.chain)
        op = ops(strcmp({ops.name}, a.chain(q).name));
        pt = arrayfun(@(i) sprintf('%s %g', op.params(i).label, a.chain(q).p(i)), 1:min(numel(op.params), numel(a.chain(q).p)), 'UniformOutput', false);
        lines = [lines, {sprintf('  %d. %s:  %s', q, a.chain(q).name, strjoin(pt, ', '))}]; %#ok<AGROW>
    end
    lines = [lines, {'To add them yourself: below "Border (padding)" are four rows "Filter 1" to "Filter 4". Click the list of Filter 1 (it says "(none)"), choose the filter, type the numbers into the white fields under it; then do the same for Filter 2. Then press "Recognise on filtered photo".'}];
end
if a.findAll
    lines = [lines, {'', 'Also ticks "Find ALL plates" (tab 4 Plate): every plate of the photo is boxed and read, and the crops with their readings are listed under the photos.'}];
end
lines = [lines, {'', ['Why: ' a.why], '', ['Measured: ' a.measured]}];
out = lines;
end

function A = table_()
C = @(name, p) struct('name', name, 'p', p);
E = struct('name', {}, 'p', {});
A = struct('id', {}, 'title', {}, 'chain', {}, 'why', {}, 'measured', {}, 'findAll', {});
add = @(id, title, chain, why, measured, varargin) struct('id', id, 'title', title, 'chain', chain, 'why', why, 'measured', measured, ...
                                                       'findAll', ~isempty(varargin) && varargin{1});

A(end+1) = add('night', 'Night view (dark photo, lamp glare)', E, ...
    ['The program repairs the brightness of a dark photo itself and also searches a locally equalised copy of it for the plate, so no filter is needed for the search. ' ...
     'Filters added on top did not beat doing nothing on the test photos (they amplify the noise of a dark photo). What decides a night photo is the plate: about 100 pixels wide and not burnt out by a lamp. ' ...
     'Plate smaller than that: choose "Night, small or far plate"; several cars: "Many cars at night".'], ...
    ['16 test photos made to look like night (simulated). Plates read of 16, lit street / very dark: no filter 7 / 6; bilateral 6 / 5; local equalisation 6 / 5; gamma 0.6 6 / 6; median 7 / 6. ' ...
     'With the final code (night search + character splitting) doing nothing reads 8 / 6 (characters 68.6 % / 61.9 %); the filters above were compared with the earlier code.']);
A(end+1) = add('small', 'Small or far plate (under about 100 pixels wide)', [C('Resize (change the resolution)', [2 3]), C('Unsharp masking', [1 1.2])], ...
    ['A small plate has few pixels per character, so the strokes merge. Enlarging with bicubic interpolation gives the segmentation smoother edges and a mild unsharp mask makes the strokes steeper again. ' ...
     'It cannot add detail: below about 40 pixels of plate width nothing helps. A closer photo, or "Pick vehicle..." on a bigger photo, is better.'], ...
    ['16 test photos shrunk to 40 %. Plates read of 16: no filter 4; enlarge 2x 5; enlarge 2x + unsharp 6. A hint, not a proof (16 photos).']);
A(end+1) = add('big', 'Big, close plate (over about 300 pixels wide)', E, ...
    ['A big plate already has plenty of pixels per character; a filter can only blur it or add noise. Do not shrink the photo to save time: that was the worst choice in the test.'], ...
    ['16 test photos at full size. Plates read of 16: no filter 8; shrink to half 5; Gaussian 7; unsharp 7.']);
A(end+1) = add('angled', 'Angled plate (seen from the side)', [C('Resize (change the resolution)', [1.5 3]), C('Unsharp masking', [1 1.2])], ...
    ['An angled plate is mainly a shape problem: the characters are squeezed and slanted. The program straightens the plate itself (perspective correction), and no filter can do that; ' ...
     'but enlarging 1.5 times gives the squeezed characters more pixels and a mild unsharp mask makes their strokes steeper. It helped on side views, but it is no cure for steep angles ' ...
     '(from 50 degrees on most plates stay unreadable): photograph from the front if you can. Check with "Compare with original".'], ...
    ['Plates read of 16 without / with the filters: the 6 real oblique test photos 1 / 2 of 6; test photos turned 30 degrees to the side 5 / 8, 50 degrees 4 / 6; ' ...
     'but on the front-view photos the characters fell from 74.6 % to 71.5 %. Details: docs/Filter_Guide_EN.pdf.']);
A(end+1) = add('above', 'Seen from above (high camera)', C('Local histogram equalisation (CLAHE)', [8 3]), ...
    ['From above the plate is squeezed vertically and the characters get short; the program straightens it itself. Local histogram equalisation gave more plates in the simulation but fewer correct characters, ' ...
     'and enlarging + sharpening did harm here. Treat it as a try: press "Compare with original" and keep the filter only if the reading gets better.'], ...
    ['Test photos turned 30 degrees about the horizontal axis (simulated). Plates read of 16 (characters correct): no filter 5 (72.7 %); local equalisation 7 (66.0 %); enlarge 1.5 + unsharp 4 (59.8 %).']);
A(end+1) = add('night_small', 'Night, small or far plate (street lit)', [C('Resize (change the resolution)', [2 3]), C('Unsharp masking', [1 1.2])], ...
    ['A small plate at night needs the same help as a small plate by day: enlarging 2 times gives the characters more pixels and a mild unsharp mask makes their strokes steeper. ' ...
     'The program also searches an equalised copy of a dark photo by itself. Use it only when the street is lit: for a very dark photo enlarging made things worse. Below about 40 pixels of plate width nothing helps; a plate lit red by the tail lights with lamp glare on its characters (your dark.jpg) is located but not read.'], ...
    ['16 test photos shrunk to 40 % and made to look like a lit street at night: no filter 5 plates (49.8 % of the characters), enlarge 2x + unsharp 7 (63.3 %), plus gamma 0.6 5 (56.0 %). Very dark photos: no filter 4 (43.6 %), enlarge 2x + unsharp 2 (28.5 %), plus gamma 0.6 2 (21.1 %): enlarging a very dark photo does harm. Check with "Compare with original".']);
A(end+1) = add('many', 'Many cars in the photo (traffic)', E, ...
    ['Ticks "Find ALL plates": every plate the program accepts is boxed (red: 90 pixels wide or more, orange: smaller, reading unreliable) and listed with its reading; plate-like regions that could not be read get grey dashed boxes. ' ...
     'Far plates of 40 to 65 pixels (a car far away in a 1500 pixel photo) are searched by a second pass and are usually read with 1 to 3 wrong characters (orange boxes); plates of 20 to 30 pixels cannot be found and no filter makes them readable. A bigger photo or "Pick vehicle..." (tab 4 Plate) is the cure.'], ...
    ['Regions with a plate-SVM score of at least -0.3 contained the plate in 14 of 16 test photos, also when the photos were shrunk to 40 %, with about 1 false region per photo. Reading needs about 100 pixels of plate width. Your Hong Kong traffic photo (1500 x 1000, plates of 56 and 65 pixels): DD 8218 read DD62I8 and TS 1318 read TSIJI8, the other plates were not found.'], true);
A(end+1) = add('night_many', 'Many cars at night', E, ...
    ['Like "Many cars in the photo", for a dark photo: every plate is searched, and an equalised copy of the dark photo is searched automatically. No filter is recommended (none helped on dark photos). ' ...
     'Plates that are small, lit red or hidden in lamp glare are often found but read wrongly or not at all.'], ...
    ['One real night traffic photo of yours (1710 x 855, three plates): 2 plates found, the Mini T935AK797 (read right with every filter tried) and the dark SUV 6688 EP-2 (read 6688EP2 with local equalisation or enlarging 3x, otherwise 6688EP, 6688F or 6688H); the white car (plate about 70 pixels) was missed. One photo is a hint only.'], true);
A(end+1) = add('vehicles', 'Any vehicle: motorcycle, scooter, bus, truck, taxi', [C('Resize (change the resolution)', [2 3]), C('Unsharp masking', [1 1.2])], ...
    ['Ticks "Find ALL plates", because several vehicles are in the photo, and enlarges the photo 2 times: the small plate of a scooter or a far bus only shows up after that. ' ...
     'The search is the same as for cars (trained on car plates). Two-line plates (motorcycles, scooters): when one row of characters is found, the program looks for a second row of the same size above or below it and joins the two readings with a space; ' ...
     'it needs a first row that is found, and rows as small as the 45 pixel scooter plate of your photo are too small for it. Buses and trucks with a car-like plate are treated like cars (not measured, no test photos). ' ...
     'Also, a road sign with real letters can be read as a plate (a "NO TURN ON RED" sign gave TURN).'], ...
    ['Your Indian street photo: the taxi plate is read KA53C6332 for KA53C6932 (one character wrong); the scooter plate (45 pixels wide, characters 8 pixels high) is found but only its upper row is read, and wrongly (K402K for KA02K). ' ...
     'Synthetic two-line plates (rows 150 to 350 pixels wide) were joined correctly in 5 of 6 scenes. One real photo: a hint only.'], true);
A(end+1) = add('dots', 'White and black dots (salt-and-pepper noise)', C('Median filter', 3), ...
    ['An isolated white or black dot cannot be the middle value of its neighbours, so a 3 x 3 median removes it and keeps the character edges. Use 5 only when more than 8 % of the pixels are dots.'], ...
    ['5 % dots on 16 test photos. Plates read of 16: no filter 5; median 7 (but 68.6 % -> 63.3 % of the characters).']);
A(end+1) = add('grain', 'Grainy photo (Gaussian noise, high ISO)', C('Bilateral filter (edge-preserving)', [1.5 0.15]), ...
    ['Grain changes every pixel a little; a median rounds off thin strokes and a Gaussian blur smears them. The bilateral filter averages only neighbours of similar brightness, so flat areas get clean and the strokes stay sharp.'], ...
    ['Gaussian noise on 16 test photos. Plates read of 16: no filter 8; bilateral 9; Gaussian 5x5 5; median 6.']);
A(end+1) = add('blurry', 'Blurry photo (out of focus or shaky)', C('Unsharp masking', [1.5 1.5]), ...
    ['Unsharp masking makes blurred edges steeper. The gain is small and not reliable, and motion blur is not repaired. Take the photo again if you can.'], ...
    ['Gaussian blur (sigma 2) on 16 test photos. Plates read of 16: no filter 5; unsharp 6; Richardson-Lucy 5.']);
A(end+1) = add('lowcontrast', 'Low contrast (haze, fog, rain, dirty glass)', C('Contrast stretching', [1 99]), ...
    ['Everything lies in a narrow band of grey levels. Stretching the 1 % to 99 % range to full black and white restores the difference between strokes and plate. The program does this by itself for very flat photos, so the gain is small.'], ...
    ['Contrast squeezed to 30 % on 16 test photos. Plates read of 16: 9 with and without the filter; characters 81.2 % -> 83.0 %.']);
A(end+1) = add('shadow', 'Shadow or uneven light across the photo', C('Illumination correction', [40 1]), ...
    ['A shadow across the plate hides the strokes on the dark side. Dividing by the slowly changing light brings both sides to the same level. Local histogram equalisation is the alternative. Do not add a gamma: the program already repairs the overall brightness.'], ...
    ['Shading (one side 4x darker) on 16 test photos. Plates read of 16: no filter 6; illumination correction 8 (characters 72.0 % -> 70.3 %).']);
A(end+1) = add('glare', 'Glare or burnt-out plate (head-lamp, flash, sun)', E, ...
    ['Pure white pixels carry no information any more, so no filter can bring the characters back. Take the photo again from another angle or without flash.'], ...
    ['Not a filter problem; nothing to measure.']);
A(end+1) = add('screen', 'Photo of a screen (pixel grid, moire)', C('Frequency low-pass (noise)', 0.5), ...
    ['A camera pointed at a monitor records the monitor''s own pixel grid and colour fringes. They are regular and very fine, so a low-pass filter removes them. Best of all: open the original image file in the app instead of photographing the screen.'], ...
    ['Not measured (no test photos of screens): a reasoned suggestion only.']);
end
